/**
 * v0.8 视觉交互层 · 洛琪希手绘钢笔淡彩分层交互小人（双形态切换 + 光标视线追踪 + 前后双平面扒边对齐）
 * ---------------------------------------------------------------------------------------------------
 * 设计要点：
 *  1. 采用真实日式钢笔淡彩分层手绘贴图（自包含 Retina WebP 数据，零外部路径依赖，亮暗双模式边缘净色无白边）
 *  2. 双形态无缝切换：轻点小人即可在「脱帽呆毛」与「标志性巫师帽」间切换（五官与披风 1:1 像素对齐）
 *  3. 桌宠级光标视线跟随：分层眼白底床 + 独立可动水彩虹膜 + 视差双高光 + 原生上睫毛遮罩 + 自然单线眨眼
 *  4. 零显存驻留开关：关闭「洛琪希视线跟随光标」或当前主题「动态效果」时，立即注销监听、停止 RAF 与定时器并移除合成层
 *  5. 物理双平面扒边贴合：躯干层置于侧栏首张面板上沿后方（z-index: 1），小手层轻搭于面板上边框前方（z-index: 4），任何缩放比例均 0px 错位
 */
const { h, motionTier } = require("./v07-core.js");
const { isMobileEnv } = require("./platform-env.js");

const ROXY_RIG_META = {
  canvasW: 460,
  canvasH: 368,
  eyePatch: {"leftPct": 34.5652, "topPct": 51.087, "widthPct": 30.8696, "heightPct": 8.9674},
  leftEye: {"cxPct": 41.4535, "cyPct": 56.032},
  rightEye: {"cxPct": 58.4302, "cyPct": 56.032},
  irisSizePctW: 7.3913,
  irisSizePctH: 9.2391,
  pawsAspect: 0.2429
};

const ROXY_RIG_ASSETS = {
  hatless: "data:image/webp;base64,",
  hatted: "data:image/webp;base64,",
  eyeFg: "data:image/webp;base64,",
  eyeBlink: "data:image/webp;base64,",
  iris: "data:image/webp;base64,",
  highlight: "data:image/webp;base64,",
  paws: "data:image/webp;base64,"
};

function prefersReducedMotion() {
  try {
    return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  } catch (_) {
    return false;
  }
}

function createIrisNode(eyeCoord, sideCls) {
  const halfW = ROXY_RIG_META.irisSizePctW / 2;
  const halfH = ROXY_RIG_META.irisSizePctH / 2;
  const baseStyle = {
    left: `${(eyeCoord.cxPct - halfW).toFixed(4)}%`,
    top: `${(eyeCoord.cyPct - halfH).toFixed(4)}%`,
    width: `${ROXY_RIG_META.irisSizePctW}%`,
    height: `${ROXY_RIG_META.irisSizePctH}%`
  };
  const irisImg = h("img.bm8-rx-iris", {
    cls: sideCls,
    style: baseStyle,
    attr: { src: ROXY_RIG_ASSETS.iris, alt: "", draggable: "false", decoding: "async" }
  });
  const hlImg = h("img.bm8-rx-hl", {
    cls: sideCls,
    style: baseStyle,
    attr: { src: ROXY_RIG_ASSETS.highlight, alt: "", draggable: "false", decoding: "async" }
  });
  return { irisImg, hlImg };
}

/**
 * 构建用于「外观」主题卡片缩略预览的轻量静态洛琪希节点（叠齐虹膜、高光与睫毛前景，杜绝白眼无瞳）
 */
function createRoxyMiniPreviewEl(hatOn = false) {
  const ep = ROXY_RIG_META.eyePatch;
  const patchStyle = {
    left: `${ep.leftPct}%`,
    top: `${ep.topPct}%`,
    width: `${ep.widthPct}%`,
    height: `${ep.heightPct}%`
  };
  const leftEyeNodes = createIrisNode(ROXY_RIG_META.leftEye, "is-left");
  const rightEyeNodes = createIrisNode(ROXY_RIG_META.rightEye, "is-right");
  return h("span.bm8-tp-roxy-live", [
    h("img.bm8-tp-roxy-base", {
      attr: {
        src: hatOn ? ROXY_RIG_ASSETS.hatted : ROXY_RIG_ASSETS.hatless,
        alt: "",
        draggable: "false",
        decoding: "async"
      }
    }),
    leftEyeNodes.irisImg,
    rightEyeNodes.irisImg,
    leftEyeNodes.hlImg,
    rightEyeNodes.hlImg,
    h("img.bm8-rx-eye-fg", {
      style: patchStyle,
      attr: { src: ROXY_RIG_ASSETS.eyeFg, alt: "", draggable: "false", decoding: "async" }
    })
  ]);
}

/**
 * 将洛琪希分层探头组件挂载到侧栏首张卡片外包槽位（物理双平面遮挡：后层探头躯干 + 前层扒边小手）
 * @param {HTMLElement} panelEl 侧栏顶置面板（如「关注直播间」或「看番动态」）
 * @param {Object} opts { hatOn, gazeOn, motionOn, onToggleHat(nextHat) }
 */
function mountRoxyPanelRig(panelEl, opts = {}) {
  if (!panelEl || !panelEl.parentNode) return null;

  let hatOn = Boolean(opts.hatOn);
  let gazeOn = opts.gazeOn !== false;
  let motionOn = opts.motionOn !== false;

  const slot = h("div.bm8-roxy-panel-slot", {
    attr: {
      "data-hat": hatOn ? "on" : "off",
      "data-gaze": gazeOn && motionOn ? "on" : "off"
    }
  });

  panelEl.parentNode.insertBefore(slot, panelEl);

  const ep = ROXY_RIG_META.eyePatch;
  const patchStyle = {
    left: `${ep.leftPct}%`,
    top: `${ep.topPct}%`,
    width: `${ep.widthPct}%`,
    height: `${ep.heightPct}%`
  };

  const imgHatless = h("img.bm8-rx-base.is-hatless", {
    cls: hatOn ? "" : "is-shown",
    attr: { src: ROXY_RIG_ASSETS.hatless, alt: "洛琪希（脱帽形态）", draggable: "false", decoding: "async" }
  });
  const imgHatted = h("img.bm8-rx-base.is-hatted", {
    cls: hatOn ? "is-shown" : "",
    attr: { src: ROXY_RIG_ASSETS.hatted, alt: "洛琪希（巫师帽形态）", draggable: "false", decoding: "async" }
  });

  const leftEyeNodes = createIrisNode(ROXY_RIG_META.leftEye, "is-left");
  const rightEyeNodes = createIrisNode(ROXY_RIG_META.rightEye, "is-right");

  const eyeFgImg = h("img.bm8-rx-eye-fg", {
    style: patchStyle,
    attr: { src: ROXY_RIG_ASSETS.eyeFg, alt: "", draggable: "false", decoding: "async" }
  });
  const blinkImg = h("img.bm8-rx-eye-blink", {
    style: patchStyle,
    attr: { src: ROXY_RIG_ASSETS.eyeBlink, alt: "", draggable: "false", decoding: "async" }
  });

  const rigCanvas = h("div.bm8-rx-canvas", [
    imgHatless,
    imgHatted,
    leftEyeNodes.irisImg,
    rightEyeNodes.irisImg,
    leftEyeNodes.hlImg,
    rightEyeNodes.hlImg,
    eyeFgImg,
    blinkImg
  ]);

  const hitbox = h("div.bm8-rx-hitbox", {
    attr: {
      role: "button",
      tabindex: "0"
    }
  });

  const backWrap = h("div.bm8-roxy-peek-back", [rigCanvas, hitbox]);
  const pawsWrap = h("div.bm8-roxy-peek-paws", { attr: { "aria-hidden": "true" } }, [
    h("img.bm8-rx-paws-img", {
      attr: { src: ROXY_RIG_ASSETS.paws, alt: "", draggable: "false", decoding: "async" }
    })
  ]);

  slot.appendChild(backWrap);
  slot.appendChild(panelEl);
  slot.appendChild(pawsWrap);

  let rafId = 0;
  let blinkTid = 0;
  let blinkCloseTid = 0;
  let popTid = 0;
  let tx = 0;
  let ty = 0;
  let cx = 0;
  let cy = 0;
  let listening = false;

  const triggerBlink = (doubleBlink = false) => {
    if (!slot.isConnected) return;
    blinkImg.classList.add("is-blinking");
    if (blinkCloseTid) clearTimeout(blinkCloseTid);
    blinkCloseTid = setTimeout(() => {
      blinkImg.classList.remove("is-blinking");
      if (doubleBlink && slot.isConnected) {
        setTimeout(() => {
          if (!slot.isConnected) return;
          blinkImg.classList.add("is-blinking");
          setTimeout(() => blinkImg.classList.remove("is-blinking"), 115);
        }, 110);
      }
    }, 125);
  };

  const scheduleNextBlink = () => {
    if (blinkTid) clearTimeout(blinkTid);
    blinkTid = 0;
    if (!listening || !slot.isConnected) return;
    const delay = 3600 + Math.random() * 3400;
    blinkTid = setTimeout(() => {
      if (!document.hidden && slot.isConnected && listening) {
        triggerBlink(Math.random() < 0.16);
      }
      scheduleNextBlink();
    }, delay);
  };

  const applyOffsets = (ix, iy) => {
    slot.style.setProperty("--rx-ix", `${ix.toFixed(2)}px`);
    slot.style.setProperty("--rx-iy", `${iy.toFixed(2)}px`);
    slot.style.setProperty("--rx-hx", `${(ix * 0.72).toFixed(2)}px`);
    slot.style.setProperty("--rx-hy", `${(iy * 0.72).toFixed(2)}px`);
    slot.style.setProperty("--rx-tilt", `${(ix * 0.36).toFixed(2)}deg`);
    slot.style.setProperty("--rx-sway", `${(ix * 0.42).toFixed(2)}px`);
  };

  const stepGaze = () => {
    rafId = 0;
    if (!listening || !slot.isConnected) return;
    cx += (tx - cx) * 0.18;
    cy += (ty - cy) * 0.18;
    applyOffsets(cx, cy);
    if (Math.abs(tx - cx) > 0.02 || Math.abs(ty - cy) > 0.02) {
      rafId = requestAnimationFrame(stepGaze);
    }
  };

  const onPointerMove = (e) => {
    if (!listening || !slot.isConnected) return;
    const rect = eyeFgImg.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return;
    const ex = rect.left + rect.width * 0.5;
    const ey = rect.top + rect.height * 0.52;
    const dx = e.clientX - ex;
    const dy = e.clientY - ey;
    // 平滑双曲正切归一化：近处细腻灵敏，远处柔和饱和不翻白眼
    const nx = Math.tanh(dx / 260);
    const ny = Math.tanh(dy / 210);
    const scale = rect.width / (ROXY_RIG_META.canvasW * (ROXY_RIG_META.eyePatch.widthPct / 100));
    // 在 460px 画布空间允许 ±5.2px 横向、±2.5px 纵向虹膜位移（约合 1024 空间 ±11.5px / ±5.5px）
    tx = nx * 5.2 * scale;
    ty = ny * 2.5 * scale;
    if (!rafId) rafId = requestAnimationFrame(stepGaze);
  };

  const onWindowBlur = () => {
    tx = 0;
    ty = 0;
    if (listening && !rafId) rafId = requestAnimationFrame(stepGaze);
  };

  const isCoarseTouch = () => {
    if (isMobileEnv()) return true;
    try {
      return Boolean(
        typeof window !== "undefined" &&
          window.matchMedia &&
          window.matchMedia("(hover: none) and (pointer: coarse)").matches
      );
    } catch (_) {
      return false;
    }
  };

  const startTracking = () => {
    if (listening || prefersReducedMotion()) return;
    listening = true;
    const coarse = isCoarseTouch();
    slot.setAttribute("data-gaze", coarse ? "off" : "on");
    if (!coarse) {
      window.addEventListener("pointermove", onPointerMove, { passive: true });
      window.addEventListener("blur", onWindowBlur, { passive: true });
    }
    scheduleNextBlink();
  };

  const stopTracking = () => {
    listening = false;
    slot.setAttribute("data-gaze", "off");
    if (rafId) cancelAnimationFrame(rafId);
    rafId = 0;
    if (blinkTid) clearTimeout(blinkTid);
    blinkTid = 0;
    if (blinkCloseTid) clearTimeout(blinkCloseTid);
    blinkCloseTid = 0;
    if (popTid) clearTimeout(popTid);
    popTid = 0;
    blinkImg.classList.remove("is-blinking");
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("blur", onWindowBlur);
    tx = 0;
    ty = 0;
    cx = 0;
    cy = 0;
    applyOffsets(0, 0);
  };

  const syncTrackingState = () => {
    const rootEl = slot.closest(".bm7-root");
    const rootTier = rootEl
      ? typeof motionTier === "function"
        ? motionTier(rootEl)
        : rootEl.getAttribute("data-bm7-motion-tier") || (rootEl.getAttribute("data-bm7-motion") === "off" ? "off" : "full")
      : motionOn === "lite"
      ? "lite"
      : motionOn
      ? "full"
      : "off";
    if (gazeOn && rootTier === "full") {
      startTracking();
    } else {
      stopTracking();
    }
  };

  const toggleHat = (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    hatOn = !hatOn;
    slot.setAttribute("data-hat", hatOn ? "on" : "off");
    imgHatless.classList.toggle("is-shown", !hatOn);
    imgHatted.classList.toggle("is-shown", hatOn);

    const rootEl = slot.closest(".bm7-root");
    const allowAnim = rootEl
      ? (typeof motionTier === "function" ? motionTier(rootEl) : rootEl.getAttribute("data-bm7-motion")) !== "off"
      : !prefersReducedMotion();
    if (allowAnim) {
      triggerBlink(false);
      rigCanvas.classList.remove("is-hat-pop");
      pawsWrap.classList.remove("is-paw-tap");
      void rigCanvas.offsetWidth;
      rigCanvas.classList.add("is-hat-pop");
      pawsWrap.classList.add("is-paw-tap");
      if (popTid) clearTimeout(popTid);
      popTid = setTimeout(() => {
        rigCanvas.classList.remove("is-hat-pop");
        pawsWrap.classList.remove("is-paw-tap");
      }, 380);
    }
    if (typeof opts.onToggleHat === "function") {
      opts.onToggleHat(hatOn);
    }
  };
  hitbox.addEventListener("click", toggleHat);
  hitbox.addEventListener("keydown", (ev) => {
    if (ev.key === "Enter" || ev.key === " ") toggleHat(ev);
  });

  // 自动在 DOM 移除时回收所有监听与定时器（零僵尸监听）
  const cleanupCheckTid = setInterval(() => {
    if (!slot.isConnected) {
      stopTracking();
      clearInterval(cleanupCheckTid);
    }
  }, 4000);

  syncTrackingState();

  const handle = {
    el: slot,
    update(nextOpts = {}) {
      if (typeof nextOpts.hatOn === "boolean" && nextOpts.hatOn !== hatOn) {
        hatOn = nextOpts.hatOn;
        slot.setAttribute("data-hat", hatOn ? "on" : "off");
        imgHatless.classList.toggle("is-shown", !hatOn);
        imgHatted.classList.toggle("is-shown", hatOn);
      }
      if (typeof nextOpts.gazeOn === "boolean") gazeOn = nextOpts.gazeOn;
      if (typeof nextOpts.motionOn === "boolean" || typeof nextOpts.motionOn === "string") motionOn = nextOpts.motionOn;
      syncTrackingState();
    },
    destroy() {
      clearInterval(cleanupCheckTid);
      stopTracking();
    }
  };
  slot._bm8RoxyRig = handle;
  return handle;
}

const ROXY_LIVE_RIG_CSS = String.raw`
/* ================= 洛琪希手绘钢笔淡彩分层交互小人（物理双平面扒边对齐） ================= */
.bm8-roxy-panel-slot {
  --rx-ix: 0px;
  --rx-iy: 0px;
  --rx-hx: 0px;
  --rx-hy: 0px;
  --rx-tilt: 0deg;
  --rx-sway: 0px;
  position: relative;
  margin-top: 138px;
  min-width: 0;
}
.bm8-roxy-panel-slot[data-hat="on"] {
  margin-top: 146px;
}
.bm8-roxy-panel-slot > .bm7-panel {
  position: relative;
  z-index: 2;
}

/* 后平面（z-index: 1）：躯干自然探出并延伸至卡片上边框后方 11px，由卡片实体背景物理遮挡 + 精确底边裁切兜底，0px 悬空或越界 */
.bm8-roxy-peek-back {
  position: absolute;
  right: 12px;
  bottom: calc(100% - 11px);
  width: 204px;
  aspect-ratio: 460 / 368;
  z-index: 1;
  pointer-events: none;
  clip-path: inset(-32px -36px 10.5px -36px);
}

/* 前平面（z-index: 4）：两只小巧手绘圆润手指轻搭在面板上边框正前方 */
.bm8-roxy-peek-paws {
  position: absolute;
  right: calc(12px + (204px - 70px) / 2);
  top: -6.5px;
  width: 70px;
  z-index: 4;
  pointer-events: none;
  transform-origin: 50% 35%;
}
.bm8-rx-paws-img {
  display: block;
  width: 100%;
  height: auto;
  user-select: none;
  filter: drop-shadow(0 1.5px 2px rgb(40 28 16 / .14));
}
.theme-dark .bm8-rx-paws-img {
  filter: brightness(.95) drop-shadow(0 2px 3px rgb(0 0 0 / .42));
}

.bm8-rx-canvas {
  position: relative;
  width: 100%;
  height: 100%;
  transform-origin: 50% 94%;
  transform: translate3d(var(--rx-sway, 0px), 0, 0) rotate(var(--rx-tilt, 0deg));
}
.bm7-root[data-bm7-motion="on"] .bm8-roxy-panel-slot[data-gaze="on"] .bm8-rx-canvas {
  will-change: transform;
}
.bm7-root[data-bm7-motion="on"] .bm8-roxy-peek-back {
  animation: bm8-rx-float 6.8s ease-in-out infinite;
}

.bm8-rx-base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: 0;
  pointer-events: none;
  user-select: none;
  transition: opacity .20s ease;
  filter: drop-shadow(0 4px 10px rgb(48 38 24 / .10));
}
.theme-dark .bm8-rx-base {
  filter: brightness(.95) saturate(.98) drop-shadow(0 6px 14px rgb(0 0 0 / .38));
}
.bm8-rx-base.is-shown {
  opacity: 1;
}

/* 分层水彩虹膜与双层视差高光 */
.bm8-rx-iris,
.bm8-rx-hl {
  position: absolute;
  display: block;
  pointer-events: none;
  user-select: none;
}
.bm8-rx-iris {
  z-index: 2;
  transform: translate3d(var(--rx-ix, 0px), var(--rx-iy, 0px), 0);
}
.bm8-rx-hl {
  z-index: 3;
  transform: translate3d(var(--rx-hx, 0px), var(--rx-hy, 0px), 0);
}
.bm7-root[data-bm7-motion="on"] .bm8-roxy-panel-slot[data-gaze="on"] .bm8-rx-iris,
.bm7-root[data-bm7-motion="on"] .bm8-roxy-panel-slot[data-gaze="on"] .bm8-rx-hl {
  will-change: transform;
}

/* 原生上睫毛/眼眶前景遮罩与自然单线眨眼层 */
.bm8-rx-eye-fg,
.bm8-rx-eye-blink {
  position: absolute;
  display: block;
  pointer-events: none;
  user-select: none;
}
.bm8-rx-eye-fg {
  z-index: 4;
}
.bm8-rx-eye-blink {
  z-index: 5;
  opacity: 0;
  transform: translateY(-1.5px) scaleY(.92);
  transform-origin: 50% 24%;
  transition: opacity .065s ease, transform .075s ease;
}
.bm8-rx-eye-blink.is-blinking {
  opacity: 1;
  transform: translateY(0) scaleY(1);
}
.theme-dark .bm8-rx-eye-fg,
.theme-dark .bm8-rx-eye-blink {
  filter: brightness(.95) saturate(.98);
}

/* 轻点切换脱帽/巫师帽的透明交互热区（不遮挡下方卡片按钮） */
.bm7-root .bm8-rx-hitbox {
  position: absolute !important;
  left: 16% !important;
  right: 16% !important;
  top: 6% !important;
  bottom: 10px !important;
  height: auto !important;
  min-height: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  z-index: 6;
  border-radius: 42% 42% 18% 18% !important;
}
.bm7-root .bm8-rx-hitbox:focus-visible {
  outline: 2px dashed var(--bm7-accent) !important;
  outline-offset: 2px;
}

.bm8-rx-canvas.is-hat-pop {
  animation: bm8-rx-hat-pop .36s cubic-bezier(.22, 1.35, .36, 1);
}
.bm8-roxy-peek-paws.is-paw-tap {
  animation: bm8-rx-paw-tap .32s cubic-bezier(.22, 1.3, .36, 1);
}

@keyframes bm8-rx-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2.2px); }
}
@keyframes bm8-rx-hat-pop {
  0% { transform: translate3d(var(--rx-sway, 0px), 0, 0) scale(1); }
  40% { transform: translate3d(var(--rx-sway, 0px), 3.5px, 0) scale(.975, 1.02) rotate(-1.2deg); }
  78% { transform: translate3d(var(--rx-sway, 0px), -2px, 0) scale(1.015, .99) rotate(.7deg); }
  100% { transform: translate3d(var(--rx-sway, 0px), 0, 0) scale(1); }
}
@keyframes bm8-rx-paw-tap {
  0%, 100% { transform: translateY(0); }
  45% { transform: translateY(-2.5px) scale(1.03); }
}

/* 外观卡片缩略图内的手绘洛琪希预览（严格锁定 460:368 比例，确保分层虹膜/高光/睫毛 1:1 对齐） */
.bm8-tp-roxy-live {
  position: absolute;
  right: 0;
  bottom: -4px;
  width: 72px;
  aspect-ratio: 460 / 368;
  height: auto;
  pointer-events: none;
  display: block;
}
.bm8-tp-roxy-live > .bm8-tp-roxy-base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: fill;
  display: block;
  z-index: 1;
}
.bm7-root[data-bm7-motion-tier="lite"] .bm8-roxy-peek-back .bm8-rx-canvas {
  animation: none !important;
}

/* 中窄屏侧栏下移时自动收起探头小人，避免与右下角常驻像素洛琪希同侧拥挤 */
@container bm7stage (max-width: 1079px) {
  .bm8-roxy-panel-slot,
  .bm8-roxy-panel-slot[data-hat="on"] {
    margin-top: 0 !important;
  }
  .bm8-roxy-peek-back,
  .bm8-roxy-peek-paws {
    display: none !important;
  }
}
`;

